#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-move-a-client-to-https. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p during after
printf '%s\n' 'hello from surl' > during/hello.txt
printf '%s\n' 'hello from surl' > after/hello.txt
cat > requests.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Lists the requests a surl --trace-ascii file records: scheme, method, path, status.
# surl traces an exchange's last lines a moment after its client has gone: wait, at most 10 s,
# until every exchange the trace opened has ended.
i=0; until [ "$(grep -c 'Exchange [0-9]* opened: ' "$1")" -eq "$(grep -c 'Exchange [0-9]* ended; ' "$1")" ]; do i=$((i+1)); [ $i -ge 100 ] && break; sleep 0.1; done
awk '/ opened: / { scheme[$1] = $6 }
     / \* GET / { sub(/:$/, "", $4); sub(/,$/, "", $5); print scheme[$1], $3, $4, $5 }' "$1"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory during --cert server.pem --key server.key --trace-ascii during.log http://127.0.0.1:8080/ https://127.0.0.1:8081/ &
sleep 1
curl --proto =https --cacert server.pem https://127.0.0.1:8081/hello.txt
kill $(jobs -p)
